contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 attackerDeposit, uint256 honestDeposit) public {
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        honestDeposit = bound(honestDeposit, 1, 1 ether);

        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        address honest = address(0xBEEF);
        vm.deal(address(attacker), attackerDeposit);
        vm.deal(honest, honestDeposit);

        vm.prank(address(attacker));
        c.deposit{value: attackerDeposit}();

        vm.prank(honest);
        c.deposit{value: honestDeposit}();

        vm.prank(address(attacker));
        try c.withdrawAll() {
        } catch {
        }

        assertTrue(address(c).balance == honestDeposit);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO target;
    bool reentered;
    constructor(address _target) {
        target = ReentrancyDAO(_target);
        reentered = false;
    }
    function deposit() external payable {
        (bool ok, ) = address(target).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            try target.withdrawAll() {
            } catch {
            }
        }
    }
}
